(function(){
'use strict';
const C=window.RevDeskCore,D=window.RevDeskData,app=document.getElementById('app'),dialog=document.getElementById('dialog');
const KEY='revdesk:v3:workspace',DEMO_KEY='revdesk:v3:practice';
let practice=window.REVENUE_DESK_PREVIEW===true,view=window.REVENUE_DESK_PREVIEW?'desk':'today',pane='flow',filter='open',query='',range='today',guideId='open',toastTimer,storageWarning='',conflict=false,answerDraft='',answerKey='',noteTimer;
let data=practice?loadPractice():loadWorkspace(),catalog=data.catalog||D.catalog,lastFocus=null;
let deskSection='overview',deskFocus=false,coachVisible=true,catalogEntity='',lastDeskKey='',deskScrolls=new Map();
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',phone:'M5 3h4l2 5-3 2a16 16 0 0 0 6 6l2-3 5 2v4c0 1-1 2-2 2C10 21 3 14 3 5c0-1 1-2 2-2Z',chart:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2',book:'M12 6c-3-3-7-3-10-2v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-3-1-7-1-10 2Z M12 6v15',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M18 6 6 18',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0Z M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z m-2 5 6 6',copy:'M8 8h12v13H8z M16 8V3H3v13h5',download:'M12 3v12 m-5-5 5 5 5-5 M3 16v5h18v-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',edit:'m15 4 5 5 M4 20l5-1L21 7l-4-4L5 15Z',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z m-5 10 3 3 6-6',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',pause:'M8 5v14 M16 5v14',play:'m7 4 14 8-14 8Z',wallet:'M3 5h17v15H3z M16 10h6v6h-6z',message:'M3 3h18v14H8l-5 4Z M7 7h10 M7 11h6',logout:'M9 3H3v18h6 M10 12h12 m-5-5 5 5-5 5',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z'};
const icon=n=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+(icons[n]||icons.info)+'"/></svg>';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=h;
const active=()=>data.deals.find(d=>d.id===data.activeId)||null;
const live=()=>data.sessions.find(s=>!s.endedAt);
const initials=n=>(n||'?').trim().split(/\s+/).slice(0,2).map(s=>s[0]||'').join('').toUpperCase();
const btn=(label,action,cls='',extra='')=>'<button type="button" class="btn '+cls+'" data-action="'+action+'" '+extra+'>'+label+'</button>';
const pill=(label,cls='')=>'<span class="pill '+cls+'">'+h(label)+'</span>';
const stamp=(at,options={})=>at?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:data.settings.timeZone,...options}).format(new Date(at)):'Not scheduled';
const dateToday=()=>C.dayKey(new Date().toISOString(),data.settings.timeZone);
const pct=n=>n===null?'—':Math.round(n*100)+'%';
const timeLength=seconds=>Math.floor(seconds/60).toString().padStart(2,'0')+':'+Math.floor(seconds%60).toString().padStart(2,'0');
const typeStatus=d=>{const s=C.status(data,d);return pill(s,['Paid','Activated'].includes(s)?'good':['Follow-up','Accepted','Authorized'].includes(s)?'warn':['Declined','Refunded'].includes(s)?'bad':'');};
function loadWorkspace(){
 try{const raw=localStorage.getItem(KEY);if(raw){const w=C.validateWorkspace(JSON.parse(raw));if(w.catalog)w.catalog=D.validateCatalog(w.catalog);return w;}
 const old=localStorage.getItem('zbcm_june_call');return old?C.migrateLegacy(JSON.parse(old)):C.workspace();}
 catch(e){storageWarning='Existing data could not be loaded. It has been left untouched. Export a backup or resolve storage access before saving.';conflict=true;return C.workspace();}
}
function loadPractice(){try{const raw=localStorage.getItem(DEMO_KEY);return raw?C.validateWorkspace(JSON.parse(raw)):D.demo(C);}catch(_){const w=D.demo(C);try{w.revision=JSON.parse(localStorage.getItem(DEMO_KEY)||'{}').revision||0;}catch(__){}return w;}}
function persist(){
 const key=practice?DEMO_KEY:KEY;
 const revision=data.revision;
 if(conflict&&!practice){renderWarning();return false;}
 try{const raw=localStorage.getItem(key),stored=raw?JSON.parse(raw):null;
 if(stored&&stored.revision!==data.revision){conflict=true;storageWarning='Another tab changed this workspace. Export your unsaved work, then reload to use the latest saved data.';renderWarning();return false;}
 data.revision=(data.revision||0)+1;localStorage.setItem(key,JSON.stringify(data));storageWarning='';renderWarning();return true;
 }catch(e){data.revision=revision;storageWarning='This browser could not save your changes. Keep this tab open and export a backup.';renderWarning();return false;}
}
function renderWarning(){const el=document.getElementById('storage-warning');if(el){el.hidden=!storageWarning;el.innerHTML=h(storageWarning)+'<button data-action="backup">Export backup</button>';}}
function save(message){const ok=persist();if(message)toast(ok?message:'Saved only in this tab. Export a backup.');return ok;}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function catalogNow(){catalog=data.catalog||D.catalog;return catalog;}
function openModal(title,body,wide=false){lastFocus=document.activeElement;dialog.classList.toggle('wide',wide);dialog.innerHTML='<div class="dialog-head"><h2 id="dialog-title">'+h(title)+'</h2><button class="iconbtn" data-action="dismiss" aria-label="Close dialog">'+icon('close')+'</button></div><div class="dialog-body">'+body+'</div>';if(!dialog.open)dialog.showModal();const first=dialog.querySelector('input:not([type=checkbox]):not([type=file]),textarea,select');if(first)setTimeout(()=>first.focus(),0);}
function closeModal(){dialog.close();if(lastFocus&&lastFocus.isConnected)lastFocus.focus();}
const form=(kind,content,submit='Save',extra='')=>'<form data-form="'+kind+'" '+extra+'><div class="form-error" role="alert"></div>'+content+'<div class="form-actions">'+btn('Cancel','dismiss','ghost')+'<button type="submit" class="btn primary">'+h(submit)+'</button></div></form>';
const field=(label,name,value='',opts={})=>'<div class="field"><label for="f-'+name+'">'+h(label)+'</label>'+(opts.textarea?'<textarea id="f-'+name+'" name="'+name+'" '+(opts.required?'required':'')+' placeholder="'+attr(opts.placeholder||'')+'" '+(opts.rows?'rows="'+opts.rows+'"':'')+'>'+h(value)+'</textarea>':'<input id="f-'+name+'" name="'+name+'" type="'+(opts.type||'text')+'" value="'+attr(value)+'" '+(opts.required?'required':'')+' '+(opts.min!==undefined?'min="'+opts.min+'"':'')+' '+(opts.max!==undefined?'max="'+opts.max+'"':'')+' '+(opts.step?'step="'+opts.step+'"':'')+' placeholder="'+attr(opts.placeholder||'')+'">')+(opts.hint?'<small>'+h(opts.hint)+'</small>':'')+'</div>';
const select=(label,name,value,options)=>'<div class="field"><label for="f-'+name+'">'+h(label)+'</label><select id="f-'+name+'" name="'+name+'">'+options.map(([v,l])=>'<option value="'+attr(v)+'" '+(v===value?'selected':'')+'>'+h(l)+'</option>').join('')+'</select></div>';
const check=(name,label,checked=false)=>'<label class="check"><input type="checkbox" name="'+name+'" '+(checked?'checked':'')+'><span>'+h(label)+'</span></label>';
function metric(label,value,foot,i='chart'){return '<div class="stat"><div class="stat-label">'+h(label)+icon(i)+'</div><div class="stat-value mono">'+h(value)+'</div><div class="stat-foot">'+h(foot)+'</div></div>';}
const Desk=window.RevDeskOpenDesk.create({C,D,h,attr,icon,btn,pill,stamp,initials,typeStatus,state:()=>({data,catalog,section:deskSection,focus:deskFocus,coachVisible,catalogEntity,practice})});
function render(){
 const oldScroll=document.getElementById('desk-scroll');if(lastDeskKey&&oldScroll)deskScrolls.set(lastDeskKey,oldScroll.scrollTop||0);
 catalogNow();const s=live(),due=C.queue(data).filter(x=>x.task&&Date.parse(x.task.at)<=Date.now()).length;
 document.title=({today:'Today',desk:'Call desk',performance:'Performance',playbook:'Playbook'}[view])+' · Revenue Desk';
 app.innerHTML='<div class="shell '+(view==='desk'?'desk-shell':'')+'"><aside class="sidebar"><div class="brand"><div class="brand-mark">z</div><div><strong>ZenBusiness</strong><small>REVENUE DESK</small></div></div><div class="nav-label">YOUR WORKSPACE</div><nav class="nav" aria-label="Main navigation">'+[['today','grid','Today'],['desk','phone','Call desk'],['performance','chart','Performance'],['playbook','book','Playbook']].map(([key,i,label])=>'<button data-action="nav" data-view="'+key+'" class="'+(view===key?'active':'')+'" '+(view===key?'aria-current="page"':'')+' aria-label="'+label+'">'+icon(i)+'<span>'+label+'</span>'+(key==='today'&&due?'<b class="count">'+due+'</b>':'')+'</button>').join('')+'</nav><div class="sidebar-bottom"><button class="practice-link" data-action="toggle-practice"><b>'+icon('spark')+' '+(practice?'Back to your workspace':'Take a practice lap')+'</b>'+(practice?'Return to your real deals.':'Explore with sample deals.')+'</button><div class="device">'+icon('shield')+'<span>Saved on this device<br>Export backups in Settings</span></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs"><span>Workspace</span><span>/</span><b>'+({today:'Today',desk:'Call desk',performance:'Performance',playbook:'Playbook'}[view])+'</b></div><div class="top-actions">'+(s?'<button class="live-pill" data-action="resume"><i class="dot"></i>Call <span data-timer>'+timeLength((Date.now()-Date.parse(s.startedAt))/1000)+'</span></button>':'<span class="save-state"><i class="dot"></i>'+(storageWarning?'Unsaved changes':'Saved on this device')+'</span>')+'<button class="iconbtn" data-action="settings" aria-label="Settings and backups">'+icon('settings')+'</button>'+btn(icon('plus')+' New deal','new-deal','small primary')+'<span class="rep">'+initials(data.settings.repName)+'</span></div></header>'+(practice?'<div class="demo-bar"><b>Practice workspace</b> Fictional customers and transactions. Your real data is separate.<button data-action="toggle-practice">Return to real workspace</button><button data-action="reset-practice">Reset practice</button></div>':'')+'<div id="storage-warning" class="storage-alert" '+(!storageWarning?'hidden':'')+'></div><main id="main" class="'+(view==='desk'?'desk-main':'')+'" tabindex="-1">'+({today:renderToday,desk:renderDesk,performance:renderPerformance,playbook:renderPlaybook}[view])()+'</main></div></div>';
 renderWarning();updateTimers();lastDeskKey=view==='desk'?deskKey():'';if(lastDeskKey){const scroll=document.getElementById('desk-scroll');if(scroll)scroll.scrollTop=deskScrolls.get(lastDeskKey)||0;}
}
function renderToday(){
 const m=C.metrics(data,{from:dateToday(),to:dateToday()}),q=C.queue(data),top=q[0],due=q.filter(x=>x.task&&Date.parse(x.task.at)<=Date.now()).length;
 const all=data.deals.filter(d=>{const s=C.status(data,d);if(filter==='open'&&!q.some(x=>x.deal.id===d.id))return false;if(filter==='due'&&!(d.task&&!d.task.done&&Date.parse(d.task.at)<=Date.now()&&!d.doNotContact))return false;if(filter==='paid'&&C.netPaid(data,d.id)<=0)return false;if(filter==='closed'&&!['Declined','Refunded','Activated'].includes(s))return false;return [d.name,d.business,d.facts.need,d.source].join(' ').toLowerCase().includes(query.toLowerCase());});
 const order=new Map(q.map((x,i)=>[x.deal.id,i]));all.sort((a,b)=>(order.get(a.id)??99999)-(order.get(b.id)??99999)||Date.parse(b.updatedAt)-Date.parse(a.updatedAt));
 const c=active()||top?.deal,coach=c?C.coaching(c):{title:'Listen for the decision',detail:'Build a clear picture before recommending an option.',drill:'Ask who else weighs in on decisions for the business. Record what they say.'};
 return '<div class="page-head"><div><div class="eyebrow">'+h(new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric',timeZone:data.settings.timeZone}).format(new Date()))+'</div><h1>Make the next move count.</h1><p>Your conversations, commitments, and confirmed outcomes.</p></div><div class="row">'+btn(icon('plus')+' New deal','new-deal','primary')+'</div></div><section class="stats" aria-label="Today’s results">'+metric('Paid deals',m.newPaidDeals,'First confirmed payments today','check')+metric('Net collected',C.money(m.net),'Collected cash less recorded refunds','wallet')+metric('Qualified close rate',pct(m.closeRate),m.converted+' paid / '+m.qualified+' qualified deals today','target')+metric('Follow-ups due',due,'Promises and callbacks to handle','clock')+'</section><div class="home-grid"><section>'+(top?'<div class="next-card"><div class="between"><span class="eyebrow">'+icon('spark')+' YOUR NEXT CONVERSATION</span>'+pill(top.label,top.score>=90?'warn':'')+'</div><div class="row"><div class="avatar large">'+initials(top.deal.name)+'</div><div><h2>'+h(top.deal.name)+'</h2><div class="customer-line">'+h(top.deal.business||'Business not yet recorded')+'</div></div></div><p class="next-reason">'+h(top.reason)+'</p>'+(top.deal.facts.need?'<p class="quote-snippet">“'+h(top.deal.facts.need)+'”</p>':'')+'<div class="between wrap">'+btn('Open conversation '+icon('arrow'),'open-deal','primary','data-id="'+attr(top.deal.id)+'"')+'<small class="muted">'+(top.task?h(stamp(top.task.at)):'Start with their priority')+'</small></div></div>':'<div class="panel empty" style="margin-bottom:23px"><div class="empty-icon">'+icon('phone')+'</div><h2>'+(data.deals.length?'Your queue is clear.':'Your next great conversation starts here.')+'</h2><p>'+(data.deals.length?'Add a new opportunity or use All deals to revisit a customer.':'Add a customer and we’ll help you find the right question, build a fitting offer, and keep every promise.')+'</p><div class="row wrap">'+btn(icon('plus')+' Add your first deal','new-deal','primary')+(!practice?btn('Explore a practice workspace','toggle-practice','ghost'):'')+'</div></div>')+'<div class="section-label"><h2>Deal queue</h2><span class="muted" style="font-size:11px">'+q.length+' open opportunities</span></div><div class="queue-tools"><div class="segmented" aria-label="Filter deals">'+[['open','Open'],['due','Due'],['paid','Paid'],['closed','Closed'],['all','All deals']].map(([k,l])=>'<button data-action="filter" data-filter="'+k+'" class="'+(filter===k?'active':'')+'" aria-pressed="'+(filter===k)+'">'+l+'</button>').join('')+'</div><div class="search">'+icon('search')+'<input type="search" id="deal-search" aria-label="Search deals" placeholder="Search deals" value="'+attr(query)+'"></div></div><div class="panel"><div class="table-wrap"><table class="deal-table"><thead><tr><th>Customer</th><th>Next step</th><th>Status</th><th class="cash-col">Net collected</th><th><span class="sr-only">Open</span></th></tr></thead><tbody>'+all.map(d=>{const item=q.find(x=>x.deal.id===d.id);return '<tr><td><div class="row"><div class="avatar">'+initials(d.name)+'</div><div><button class="deal-name" data-action="open-deal" data-id="'+attr(d.id)+'">'+h(d.name||'Unnamed customer')+'</button><small>'+h(d.business||'Business not recorded')+'</small></div></div></td><td>'+h(item?.reason||'Conversation complete')+'<small>'+h(d.task&&!d.task.done?stamp(d.task.at):item?.label||'')+'</small></td><td>'+typeStatus(d)+'</td><td class="cash-col mono">'+C.money(C.netPaid(data,d.id))+'</td><td><button class="iconbtn" data-action="open-deal" data-id="'+attr(d.id)+'" aria-label="Open '+attr(d.name)+'">'+icon('chevron')+'</button></td></tr>';}).join('')+'</tbody></table></div>'+(!all.length?'<div class="no-results">'+(query?'No matching customers.':'No deals in this view yet.')+'</div>':'')+'<div class="queue-footer">'+all.length+' '+(all.length===1?'deal':'deals')+' · confirmed facts, clear next steps</div></div></section><aside class="home-aside stack"><div class="panel focus-card"><div class="focus-icon">'+icon('target')+'</div><div class="eyebrow">TODAY’S COACHING FOCUS</div><h3>'+h(coach.title)+'</h3><p>'+h(coach.drill)+'</p>'+btn('Practice this conversation '+icon('arrow'),'practice-drill','small ghost','data-category="'+attr(c?.objection?.category||'authority')+'"')+'</div><div class="panel focus-card"><div class="section-label"><span class="eyebrow">DAILY PACE</span><button class="iconbtn" data-action="settings" aria-label="Edit daily goal">'+icon('edit')+'</button></div><div class="goal-num mono">'+m.newPaidDeals+' <span>/ '+data.settings.targetDeals+'</span></div><p style="margin:9px 0 0">Confirmed paid deals</p><div class="progress-track"><i style="width:'+Math.min(100,m.newPaidDeals/Math.max(1,data.settings.targetDeals)*100)+'%"></i></div><small class="faint">'+Math.max(0,data.settings.targetDeals-m.newPaidDeals)+' to your daily goal</small></div><div class="panel focus-card"><div class="eyebrow" style="margin-bottom:10px">THE QUALITY OF THE DAY</div><div class="mini-row"><span>Connected calls</span><b>'+m.connected+'</b></div><div class="mini-row"><span>Qualified deals</span><b>'+m.qualified+'</b></div><div class="mini-row"><span>Activated today</span><b>'+m.activated+'</b></div><div class="mini-row"><span>Refunds recorded</span><b>'+C.money(m.refunds)+'</b></div></div></aside></div>';
}
function renderDesk(){return Desk.render(active());}
function deskKey(){return [practice,active()?.id||'reference',deskFocus?deskSection:'all'].join(':');}
function jumpToSection(id){
 if(!Desk.sections.some(s=>s.id===id))return;
 if(dialog.open)closeModal();deskSection=id;view='desk';render();
 const target=document.getElementById('desk-'+id);target?.scrollIntoView?.({block:'start',behavior:'auto'});target?.focus?.({preventScroll:true});
}
function jumpDialog(){openModal('Jump to anything','<label for="jump-query">Find a section or action</label><input id="jump-query" type="search" placeholder="Tax, objections, payment, notes…" autocomplete="off" aria-controls="jump-results"><div id="jump-results" class="jump-results">'+Desk.searchResults('')+'</div><p class="explanation">All sections are available at any time. Enter opens the first result.</p>');}
function switchDealDialog(){openModal('Switch customer','<p>Your notes stay with the customer you are leaving.</p><div class="jump-results">'+data.deals.map(d=>'<button class="jump-result" data-action="open-deal" data-id="'+attr(d.id)+'"><span class="avatar">'+initials(d.name)+'</span><span><b>'+h(d.name)+'</b><small>'+h(d.business)+'</small></span>'+typeStatus(d)+'</button>').join('')+'</div>'+btn('Add another customer','new-deal','small primary'));}
function renderFlow(d,a){
const key=d.id+':'+(a.key||a.kind);if(answerKey!==key){answerKey=key;answerDraft='';}
let controls='';
if(a.kind==='evidence')controls='<form data-form="answer" data-key="'+a.key+'"><label for="buyer-answer">Capture their answer, in their words</label><textarea id="buyer-answer" name="answer" placeholder="What did the customer say?" required>'+h(answerDraft)+'</textarea>'+(a.key==='decision'?'<div style="margin-top:13px">'+select('Who decides?','decisionType',d.decisionType,[['unknown','Still unclear'],['solo','Customer can decide'],['shared','Shared decision']])+check('decisionReady','All required decision-makers have agreed',d.decisionReady)+'</div>':'')+'<div class="form-error" role="alert"></div><div class="answer-actions"><span class="faint" style="font-size:10px">Their words guide the recommendation.</span><button type="submit" class="btn primary">Save answer '+icon('arrow')+'</button></div></form>';
else if(a.kind==='permission')controls='<div class="row wrap">'+btn('Yes, let’s talk','permission','primary','data-value="yes"')+btn('Short on time','permission','ghost','data-value="rushed"')+btn('Not now','task','ghost')+'</div>';
else if(a.kind==='coverage')controls=btn('Review account coverage '+icon('arrow'),'coverage','primary');
else if(a.kind==='offer')controls=btn('Build the recommendation '+icon('arrow'),'pane','primary','data-pane="offer"');
else if(a.kind==='objection')controls='<div class="row wrap">'+btn('Clarify & respond','objection','primary')+btn('Agree on a next step','task','ghost')+'</div>';
else if(a.kind==='decision')controls='<div class="row wrap">'+btn('Update decision details','evidence','primary','data-key="decision"')+btn('Schedule together','task','ghost')+'</div>';
else if(a.kind==='accept')controls='<div class="row wrap">'+btn('Customer said yes','accept','primary')+btn('They have a concern','objection','ghost')+btn('They declined','decline','ghost')+'</div>';
else if(a.kind==='authorize')controls=btn('Record explicit authorization','authorize','primary');
else if(a.kind==='payment')controls=btn('Record confirmed payment','payment','primary');
else if(a.kind==='activate')controls='<div class="row wrap">'+btn('Confirm activation','activate','primary')+btn('Schedule help','task','ghost')+'</div>';
else if(['covered','closed','refunded','complete'].includes(a.kind))controls='<div class="row wrap">'+btn('Prepare the recap','pane','primary','data-pane="follow"')+(a.kind==='covered'?btn('Record no current need','decline','ghost'):a.kind==='closed'?btn('Customer asked to reopen','reopen','ghost'):'')+'</div>';
return (d.rushed?'<div class="notice warn" style="margin-bottom:15px">Short on time: stay with one priority and agree on a next step.</div>':'')+'<div class="call-card"><div class="call-top"><span class="eyebrow">'+icon('spark')+' NEXT BEST MOVE</span><span class="step-phase">'+h(a.phase)+'</span></div><div class="call-content"><h2>'+h(a.title)+'</h2><div class="say-label">'+(['payment','refunded'].includes(a.kind)?'YOUR NEXT ACTION':'ASK / SAY')+'</div><div class="question">'+h(a.question)+'</div><div class="why">'+icon('info')+'<span>'+h(a.why)+'</span></div><div class="answer-box">'+controls+'</div></div><div class="call-bottom"><button data-action="objection">'+icon('message')+' Handle a concern</button><button data-action="coverage">'+icon('shield')+' Coverage</button><button data-action="silence" data-silence>'+icon('pause')+' Pause & listen</button><button data-action="notes">'+icon('edit')+' Notes</button></div></div><div class="phase-track">'+['Discover','Recommend','Commit','Activate'].map(p=>'<span class="'+(a.phase===p||(p==='Discover'&&['Open','Clarify'].includes(a.phase))?'active':'')+'"><i></i>'+p+'</span>').join('')+'</div>'+(!d.facts.need?'<div class="reminder">'+icon('info')+'<span>A recommendation appears after you confirm the customer’s need and existing coverage.</span></div>':'');
}
function metricRange(){const to=dateToday();if(range==='all')return{from:'',to};const t=new Date();t.setUTCDate(t.getUTCDate()-(range==='week'?6:range==='month'?29:0));return{from:C.dayKey(t.toISOString(),data.settings.timeZone),to};}
function renderPerformance(){const r=metricRange(),m=C.metrics(data,r),base=C.metrics(data,{...r,cohort:'baseline'}),adapt=C.metrics(data,{...r,cohort:'adaptive'});const losses={};data.deals.filter(d=>d.disposition==='declined'&&(!r.from||C.dayKey(d.updatedAt,data.settings.timeZone)>=r.from)&&C.dayKey(d.updatedAt,data.settings.timeZone)<=r.to).forEach(d=>{const k=d.lossReason||'Not recorded';losses[k]=(losses[k]||0)+1;});return '<div class="page-head"><div><div class="eyebrow">PERFORMANCE</div><h1>Measure the outcome.</h1><p>Confirmed payments, productive conversations, and customers getting started.</p></div><div class="segmented">'+[['today','Today'],['week','7 days'],['month','30 days'],['all','All time']].map(([k,l])=>'<button data-action="range" data-range="'+k+'" class="'+(range===k?'active':'')+'">'+l+'</button>').join('')+'</div></div><section class="stats">'+metric('Paid deals',m.newPaidDeals,m.retained+' still have positive collected value','check')+metric('Net collected',C.money(m.net),C.money(m.cash)+' collected · '+C.money(m.refunds)+' refunded','wallet')+metric('Deals per call hour',m.dealsPerHour===null?'—':m.dealsPerHour.toFixed(2),m.hours.toFixed(1)+' hours across completed calls','clock')+metric('Qualified close rate',pct(m.closeRate),m.converted+' paid / '+m.qualified+' qualified deals','target')+'</section><div class="metrics-grid"><section class="panel"><div class="panel-head"><h2>Conversation outcomes</h2>'+pill(range==='today'?'Today':range==='week'?'Last 7 days':range==='month'?'Last 30 days':'All time')+'</div><div class="panel-body">'+[['Completed calls',m.calls],['Connected calls',m.connected],['Qualified deals',m.qualified],['New paid deals',m.newPaidDeals],['Activated',m.activated]].map(([l,n])=>'<div class="chart-row"><span>'+l+'</span><div class="chart-bar"><i style="width:'+(m.calls?Math.min(100,n/Math.max(m.calls,m.newPaidDeals,m.activated)*100):0)+'%"></i></div><b>'+n+'</b></div>').join('')+'<p class="explanation">Counts are separate outcomes, not a strict funnel. Qualified deals have a recorded need, decision process, confirmed gap, and a completed connected call. Close rate counts those qualified and paid within this reporting window.</p></div></section><section class="panel"><div class="panel-head"><h2>Quality beyond the sale</h2></div><div class="panel-body"><div class="mini-row"><span>Average first payment</span><b>'+ (m.revenuePerDeal===null?'—':C.money(Math.round(m.revenuePerDeal)))+'</b></div><div class="mini-row"><span>Agreed follow-ups</span><b>'+m.followUps+'</b></div><div class="mini-row"><span>Follow-ups that paid</span><b>'+m.followConverted+' / '+m.followUps+'</b></div><div class="mini-row"><span>Activations recorded</span><b>'+m.activated+'</b></div><div class="mini-row"><span>Refund transactions</span><b>'+m.refundTransactions+'</b></div><p class="explanation">Monthly plans contribute the cash actually collected. Total contract value stays separate. Follow-up conversion uses agreements and payments recorded within this period.</p></div></section><section class="panel"><div class="panel-head"><h2>Compare workflows</h2></div><div class="panel-body"><table class="compare-table"><thead><tr><th>Within selected period</th><th>Baseline</th><th>Adaptive</th></tr></thead><tbody>'+[['Qualified deals',base.qualified,adapt.qualified],['New paid deals',base.newPaidDeals,adapt.newPaidDeals],['Qualified close rate',pct(base.closeRate),pct(adapt.closeRate)],['Net collected',C.money(base.net),C.money(adapt.net)],['Completed call hours',base.hours.toFixed(1),adapt.hours.toFixed(1)]].map(row=>'<tr>'+row.map(v=>'<td>'+h(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table><p class="explanation">Tag a deal’s workflow in its details. Use comparable lead sources and time windows. These descriptive counts do not establish that a workflow caused a result.</p></div></section><section class="panel"><div class="panel-head"><h2>What held decisions back</h2></div><div class="panel-body">'+(Object.entries(losses).length?Object.entries(losses).sort((a,b)=>b[1]-a[1]).map(([l,n])=>'<div class="mini-row"><span>'+h(l)+'</span><b>'+n+'</b></div>').join(''):'<p class="muted" style="font-size:12px">No declined deals recorded in this period. Record an honest reason when a customer passes.</p>')+'<p class="explanation">Use recurring reasons to choose a coaching exercise or improve the offer.</p></div></section></div><p class="explanation">Reporting time zone: '+h(data.settings.timeZone)+'. Paid deals count the first recorded successful payment per deal. Retained count reflects all recorded refunds to date. All financial records are manually confirmed.</p>';}
function renderPlaybook(){const item=D.playbook.find(x=>x.id===guideId)||D.playbook[0];let prev='';return '<div class="page-head"><div><div class="eyebrow">PLAYBOOK</div><h1>Know the move. Stay present.</h1><p>A reference for the conversation, from the first question to the next commitment.</p></div>'+btn(icon('spark')+' Practice','practice-drill','ghost','data-category="thinking"')+'</div><div class="playbook-grid"><nav class="panel playbook-index" aria-label="Playbook sections">'+D.playbook.map(p=>{const label=p.section!==prev?'<div class="eyebrow">'+h(p.section)+'</div>':'';prev=p.section;return label+'<button data-action="guide" data-guide="'+p.id+'" class="'+(p.id===item.id?'active':'')+'">'+h(p.title)+'</button>';}).join('')+'</nav><article class="panel playbook-content"><div class="eyebrow">'+h(item.section)+'</div><h1>'+h(item.title)+'</h1><p>'+h(item.goal)+'</p><h3>A question to use</h3><div class="question">'+h(item.ask)+'</div><h3>Listen for</h3><p>'+h(item.listen)+'</p><h3>Make the next move</h3><p>'+h(item.move)+'</p><div class="notice">Use your current approved service information for prices, scope, tax or legal explanations, and terms. <a href="junecallguideofficial.html" target="_blank" rel="noopener">Open the original training guide</a> for reference.</div></article></div>';}
function dealDialog(edit=false){const d=edit?active():null,hasCalls=d&&data.sessions.some(s=>s.dealId===d.id);openModal(edit?'Customer details':'Start a new deal',form('deal','<div class="field-row">'+field('Customer name','name',d?.name||'',{required:true,placeholder:'First and last name'})+field('Business name','business',d?.business||'',{placeholder:'Business name'})+'</div><div class="field-row">'+field('Email','email',d?.email||'',{type:'email'})+field('Phone','phone',d?.phone||'',{type:'tel'})+'</div>'+field('What does the business do?','industry',d?.industry||'',{placeholder:'In their words'})+'<div class="field-row">'+select('Entity type','entity',d?.entity||'',[['','Not confirmed'],['single','Single-member LLC'],['multi','Multi-member / other entity']])+field('Lead source','source',d?.source||'Manual')+'</div>'+(hasCalls?'<p class="muted" style="font-size:12px">Workflow: '+h(d.cohort)+'. The label is locked after the first call.</p>':select('Workflow for comparison','cohort',d?.cohort||'adaptive',[['adaptive','Adaptive desk'],['baseline','Baseline workflow']])),'Save customer',d?'data-id="'+attr(d.id)+'"':''));}
function evidenceDialog(key){const d=active();openModal('Buyer evidence',form('evidence',Object.entries(C.FACTS).map(([k,l])=>field(l+' · customer’s words',k,d.facts[k],{textarea:true,rows:2,placeholder:'Not yet confirmed'})).join('')+select('Who decides?','decisionType',d.decisionType,[['unknown','Not confirmed'],['solo','Customer can decide'],['shared','Shared decision']])+check('decisionReady','All required decision-makers have agreed',d.decisionReady),'Save evidence'));if(key)setTimeout(()=>document.getElementById('f-'+key)?.focus(),0);}
function coverageDialog(){const d=active();openModal('Confirm existing coverage','<p>Use the customer’s answer and the actual account record. Include outside providers. A service is a gap only when its need and absence are confirmed.</p>'+form('coverage',Object.entries(C.SERVICES).map(([k,l])=>'<div class="coverage-form-row"><label for="coverage-'+k+'">'+h(l)+'</label><select id="coverage-'+k+'" name="'+k+'">'+[['unknown','Unknown'],['covered','Already covered'],['gap','Confirmed gap'],['na','Not relevant']].map(([v,t])=>'<option value="'+v+'" '+(d.coverage[k]===v?'selected':'')+'>'+t+'</option>').join('')+'</select><input name="note-'+k+'" aria-label="'+attr(l)+' coverage source" placeholder="Provider or evidence" value="'+attr(d.coverageNotes[k]||'')+'"></div>').join(''),'Save coverage'),true);}
function quoteDialog(productId){const d=active(),p=catalog.find(p=>p.id===productId);if(!p)throw new Error('This product is no longer in the catalog.');if(d.acceptedAt)throw new Error('Reopen the offer before changing an accepted recommendation.');const existing=d.quote?.lines[0]?.productId===p.id?d.quote:null,billing=existing?.lines[0]?.billing||(p.once?'once':'annual'),idx=d.entity==='multi'?1:0,reference=p.annual?.[idx];
openModal('Verify the recommendation','<p><b>'+h(p.name)+'</b> · '+p.services.map(k=>h(C.SERVICES[k])).join(', ')+'</p><div class="notice warn" style="margin-bottom:20px">'+h(p.source)+(reference?' · historical reference '+C.money(reference):'')+'. Enter the actual account’s current price and terms below.</div>'+form('quote','<input type="hidden" name="productId" value="'+attr(p.id)+'"><div class="field-row">'+select('Billing','billing',billing,[[p.once?'once':'annual',p.once?'One-time':'Annual'],...(p.monthly?[['monthly','Monthly installments']]:[])])+field('Verified initial price (USD)','amount',existing?(existing.lines[0].amount/100).toFixed(2):'',{required:true,type:'number',min:0.01,max:1000000,step:'0.01',placeholder:'Confirm in approved system'})+'</div><div class="field-row">'+field('Commitment in months','months',existing?.lines[0]?.months||12,{type:'number',min:1,max:60,required:true,hint:'Used for total commitment on monthly plans.'})+field('Quote valid through','expires',new Date(Date.now()+7*86400000).toISOString().slice(0,10),{type:'date',required:true,min:new Date().toISOString().slice(0,10)})+'</div>'+field('Confirmed service scope','scope',existing?.scope||'',{required:true,textarea:true,placeholder:'What is included for this specific account?'})+field('Exact terms to disclose','terms',existing?.terms||'',{required:true,textarea:true,placeholder:'Service period, total commitment, renewal amount/date, and cancellation terms.'})+field('Verification source / account reference','source',existing?.source||'',{required:true,placeholder:'Approved system and order or offer reference',hint:'Use a non-sensitive reference. Never enter card numbers or access credentials.'})+check('verified','I checked current price, scope, account eligibility, and terms in the approved system.'),'Save verified recommendation'));}
function objectionDialog(category){const d=active(),o=(category&&C.OBJECTIONS[category]&&d.objection?.category!==category)?{category,quote:'',clarification:'',resolution:'',resolved:false}:d.objection||{category:'thinking',quote:'',clarification:'',resolution:'',resolved:false};openModal('Understand the concern',form('objection',select('What did you hear?','category',o.category,Object.entries(C.OBJECTIONS).map(([k,v])=>[k,v.label]))+field('Their exact concern','quote',o.quote,{textarea:true,required:true,placeholder:'Use their words'})+'<div class="notice" id="objection-question" style="margin-bottom:18px"><span class="eyebrow">ASK TO CLARIFY</span><p style="margin-top:9px">'+h(C.OBJECTIONS[o.category].question)+'</p></div>'+field('What is actually blocking the decision?','clarification',o.clarification,{textarea:true,placeholder:'Record their answer to the clarifying question'})+'<div class="chips" id="objection-options">'+C.OBJECTIONS[o.category].options.map(t=>'<button type="button" data-action="objection-chip" data-value="'+attr(t)+'">'+h(t)+'</button>').join('')+'<div class="notice" style="margin:18px 0"><b>Tie the response to their priority</b><p style="margin-top:7px">'+h(d.facts.need?'They said: “'+d.facts.need+'”. Explain only the verified capability or evidence that addresses the clarified concern.':'First establish what they want help with. Then explain only the relevant, verified capability.')+'</p></div>'+field('What answer or evidence resolved it?','resolution',o.resolution,{textarea:true,placeholder:'Record the specific answer and the customer’s response'})+check('resolved','The customer confirmed that this concern is resolved.',o.resolved),'Save concern'));}
function taskDialog(){const d=active(),t=d.task&&!d.task.done?d.task:null;const localDate=iso=>{if(!iso)return'';const x=new Date(iso);return new Date(x.getTime()-x.getTimezoneOffset()*60000).toISOString().slice(0,16);};openModal('Make the next step specific',form('task',select('Kind of next step','kind',t?.kind||(C.netPaid(data,d.id)>0?'activation':'callback'),[['callback','Customer callback'],['promise','Answer / item you owe them'],['decision','Conversation with decision-makers'],['payment','Confirm payment outcome'],['activation','Activation assistance']])+field('Purpose','purpose',t?.purpose||'',{required:true,textarea:true,placeholder:'The actual question or decision to resolve'})+'<div class="field-row">'+field('Date and time','at',localDate(t?.at),{type:'datetime-local',required:true,hint:'Device time: '+Intl.DateTimeFormat().resolvedOptions().timeZone})+field('Owner','owner',t?.owner||data.settings.repName,{required:true,placeholder:'Who will take this action?'})+'</div>'+check('confirmed','The customer agreed to this purpose and time.',t?.confirmed||false)+'<p class="muted" style="font-size:11px">Unchecked means an internal reminder. This does not send an invitation or message.</p>','Save next step'));}
function agreementDialog(kind){const d=active(),q=d.quote;if(!q)throw new Error('Build a verified offer first.');const err=C.commitReady(d);if(err)throw new Error(err);openModal(kind==='accept'?'Record their agreement':'Record payment authorization',form(kind,'<div class="notice"><b>'+h(q.lines.map(l=>l.name).join(' + '))+'</b><p style="margin-top:8px">'+C.money(C.quoteTotal(q))+' initially · '+C.money(C.contractTotal(q))+' total commitment</p><p style="margin-top:8px">'+h(q.terms)+'</p></div>'+check('confirmed',kind==='accept'?'The customer explicitly agreed to this offer and its disclosed terms.':'The customer explicitly authorized this exact payment and its disclosed terms.')+'<p class="muted" style="font-size:11px">This records the conversation. It does not charge the customer.</p>',kind==='accept'?'Record agreement':'Record authorization'));}
function paymentDialog(refund=false){const d=active();if(!d.authorizedAt&&!refund)throw new Error('Record the customer’s agreement and authorization first.');const payments=C.paymentEvents(data,d.id).filter(p=>p.amount>data.events.filter(e=>e.type==='refund'&&e.paymentId===p.id).reduce((s,e)=>s+e.amount,0));if(refund&&!payments.length)throw new Error('No refundable payment remains.');openModal(refund?'Record a confirmed refund':'Record a confirmed payment','<p>First verify the successful '+(refund?'refund':'payment')+' in your approved system. Revenue Desk records the result; it does not move money.</p>'+form(refund?'refund':'payment',(refund?select('Original payment','paymentId',payments[0]?.id,payments.map(p=>[p.id,p.reference+' · '+C.money(p.amount)])):'')+'<div class="field-row">'+field(refund?'Amount refunded (USD)':'Amount actually collected (USD)','amount',refund?'':(C.quoteTotal(d.quote)/100).toFixed(2),{required:true,type:'number',min:0.01,max:1000000,step:'0.01'})+field(refund?'Refund reference':'Transaction reference','reference','',{required:true,placeholder:'Unique reference from the system'})+'</div>'+check('confirmed','I verified that this '+(refund?'refund':'payment')+' succeeded in the approved system.'),'Record '+(refund?'refund':'payment')));}
function activationDialog(){const d=active();openModal('Confirm customer activation',form('activation',field('What was completed?','detail','',{required:true,textarea:true,placeholder:'First consultation booked, account activated, or verified first step'})+check('confirmed','I verified this activation in the service system.'),'Record activation'));}
function endDialog(){const d=active();if(!live()||live().dealId!==d.id)throw new Error('There is no active call for this customer.');openModal('Finish this conversation',form('end-call',select('Call outcome','outcome','connected',[['connected','Connected conversation'],['no-answer','No answer / voicemail']])+'<div class="notice"><b>'+h(C.coaching(d).title)+'</b><p style="margin-top:8px">'+h(C.coaching(d).drill)+'</p></div>'+(d.task&&!d.task.done?'<p class="muted" style="margin-top:17px;font-size:12px">Next step: '+h(d.task.purpose)+' · '+h(stamp(d.task.at))+'</p>':'<p class="muted" style="margin-top:17px;font-size:12px">No next event is set. You can schedule one and copy the recap after ending the call.</p>'),'End call & prepare recap'));}
function declineDialog(){const d=active();if(C.netPaid(data,d.id)>0)throw new Error('This deal has a confirmed payment. Record any refund separately.');openModal('Record a clear decision',form('decline',select('Reason','reason',d.lossReason||'No current need',[['No current need','No current need'],['Already covered','Already covered'],['Scope mismatch','Scope mismatch'],['Budget','Budget'],['Timing','Timing'],['Trust / proof','Trust / proof'],['Approval unavailable','Approval unavailable'],['Prefers another option','Prefers another option'],['Customer declined','Customer declined']])+field('What did they say?','detail','',{textarea:true,required:true,placeholder:'Capture the reason without guessing'})+check('doNotContact','The customer asked not to be contacted.',d.doNotContact),'Record decline'));}
function reopenDialog(){const d=active();openModal('Reopen at the customer’s request',form('reopen',field('What changed?','detail','',{required:true,textarea:true,placeholder:'Record the customer’s request to resume'})+check('confirmed','The customer chose to reopen this conversation.'),'Reopen conversation'));}
function settingsDialog(){openModal('Your workspace',form('settings','<div class="field-row">'+field('Your name','repName',data.settings.repName,{placeholder:'Used in your introduction and recap'})+field('Daily paid-deal goal','targetDeals',data.settings.targetDeals,{type:'number',min:1,max:1000,required:true})+'</div>'+field('Reporting time zone','timeZone',data.settings.timeZone,{required:true,hint:'For example: America/New_York. Scheduling inputs use your device’s time zone.'})+select('Appearance','theme',document.documentElement.dataset.theme||'dark',[['dark','Dark'],['light','Light']]),'Save preferences')+'<section class="settings-section"><h3>Backups and continuity</h3><p>Deals are saved in this browser. Export a backup before changing devices or clearing site data. Restore replaces this workspace after you review it.</p><div class="row wrap">'+btn(icon('download')+' Export backup','backup','small ghost')+btn('Export deal CSV','export-csv','small ghost')+'</div><label for="restore-file" style="margin-top:17px">Restore a Revenue Desk backup</label><input class="file-input" id="restore-file" type="file" accept="application/json,.json"></section><section class="settings-section"><h3>Product catalog</h3><p>Current catalog: '+h(data.catalog?'Imported product source':'Historical June 2026 guide')+'. Every customer quote still requires current account verification. A catalog import updates reference values and scope.</p><div class="row wrap">'+btn('Export catalog template','export-catalog','small ghost')+btn('View product sources','catalog','small ghost')+'</div><label for="catalog-file" style="margin-top:17px">Import maintained catalog JSON</label><input class="file-input" id="catalog-file" type="file" accept="application/json,.json"></section><section class="settings-section"><h3>Connections</h3><p>Salesforce and payment processing are external handoffs. Copy a reviewed recap into Salesforce, process transactions in the approved system, and record their confirmed references here. No messages are sent by this app.</p></section><section class="settings-section"><h3>Practice workspace</h3><p>Sample customers and transactions are isolated from your actual records.</p>'+btn(practice?'Return to real workspace':'Open practice workspace','toggle-practice','small ghost')+'</section>',true);}
function practiceDialog(category='thinking'){const o=C.OBJECTIONS[category]||C.OBJECTIONS.thinking;const quotes={cost:'I like what you described, but that is more than I can spend today.',authority:'I need to talk with my business partner before I decide.',thinking:'Let me think about it and get back to you.',timing:'I am not ready to deal with this until the business is running.',value:'I am not sure I need everything in that package.',trust:'How do I know this service will do what you are describing?'};openModal('Practice one useful move','<p>This is a guided rehearsal with a self-review rubric. It does not record a real call or change performance metrics.</p>'+form('drill','<input type="hidden" name="category" value="'+attr(category)+'"><div class="notice"><span class="eyebrow">THE CUSTOMER SAYS</span><p style="font-family:Georgia,serif;font-size:23px;margin-top:11px">“'+h(quotes[category]||quotes.thinking)+'”</p></div>'+field('Your response','response','',{textarea:true,required:true,placeholder:'Acknowledge, then ask one useful question.'})+'<details><summary>Show the coaching cue</summary><p class="muted" style="font-size:12px;margin:10px 0">'+h(o.drill)+'</p></details>','Review my response'));}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function backup(){download(JSON.stringify(data,null,2),'revenue-desk-'+(practice?'practice-':'')+dateToday()+'.json','application/json');toast('Backup exported.');}
async function copy(value){try{await navigator.clipboard.writeText(value);toast('Copied. Review before sending or pasting.');}catch(_){openModal('Copy this text','<p>Select and copy the text below.</p><textarea readonly class="copy-block">'+h(value)+'</textarea>');dialog.querySelector('textarea').select();}}
let pendingImport=null,silenceUntil=0;
function updateTimers(){const s=live();if(s)document.querySelectorAll('[data-timer]').forEach(el=>el.textContent=timeLength(Math.max(0,(Date.now()-Date.parse(s.startedAt))/1000)));if(silenceUntil){const left=Math.ceil((silenceUntil-Date.now())/1000);document.querySelectorAll('[data-silence]').forEach(b=>b.innerHTML=left>0?icon('pause')+' Listen · '+left+'s':icon('pause')+' Pause & listen');if(left<=0)silenceUntil=0;}}
function refreshDeal(d,message){d.updatedAt=new Date().toISOString();save(message);render();}
function setView(v){view=v;query='';render();document.getElementById('main')?.focus({preventScroll:true});}
async function handleAction(button){const name=button.dataset.action,d=active();
if(name==='dismiss'){closeModal();return;}
if(name==='desk-jump'){jumpToSection(button.dataset.section);return;}
if(name==='desk-mode'){deskFocus=button.dataset.mode==='focus';jumpToSection(deskSection);return;}
if(name==='desk-focus-section'){deskFocus=true;jumpToSection(button.dataset.section);return;}
if(name==='jump-search'){jumpDialog();return;}
if(name==='switch-deal'){switchDealDialog();return;}
if(name==='catalog-entity'){catalogEntity=button.dataset.entity;render();return;}
if(name==='toggle-coach'){coachVisible=!coachVisible;if(dialog.open){openModal('Call support',Desk.support(d,true));}else render();return;}
if(name==='call-support'){openModal('Call support',Desk.support(d,true));return;}
if(name==='guided'){if(!d){openModal('Optional conversation guide','<p>Use the open call map to explore every section. Add a customer when you want suggestions based on their answers.</p>'+btn('Add customer','new-deal','primary'));}else openModal('Optional conversation guide',renderFlow(d,C.action(data,d,catalog)),true);return;}

if(name==='nav'){setView(button.dataset.view);return;}
if(name==='new-deal'){dealDialog();return;}
if(name==='edit-deal'){dealDialog(true);return;}
if(name==='open-deal'){if(dialog.open)closeModal();data.activeId=button.dataset.id;save();view='desk';pane='flow';deskSection='overview';render();return;}
if(name==='resume'){data.activeId=live().dealId;view='desk';pane='flow';render();return;}
if(name==='filter'){filter=button.dataset.filter;render();return;}
if(name==='range'){range=button.dataset.range;render();return;}
if(name==='pane'){pane=button.dataset.pane;jumpToSection({flow:'discovery',offer:'offers',follow:'recap',history:'history'}[pane]||'overview');return;}
if(name==='guide'){guideId=button.dataset.guide;render();return;}
if(name==='settings'){settingsDialog();return;}
if(name==='backup'){backup();return;}
if(name==='toggle-practice'){
 if(noteTimer){clearTimeout(noteTimer);noteTimer=null;if(!persist())throw new Error('Export your notes before switching workspaces.');}
 if(live())throw new Error('End the active call before switching workspaces.');
 if(!practice&&(storageWarning||conflict))throw new Error('Export your unsaved work and resolve the storage warning before switching workspaces.');
 if(dialog.open)closeModal();practice=!practice;conflict=false;storageWarning='';
 if(practice){data=loadPractice();}
 else data=loadWorkspace();view=practice?'desk':'today';pane='flow';deskSection='overview';deskFocus=false;filter='open';query='';save();render();return;
}
if(name==='reset-practice'){if(!practice)return;if(live())throw new Error('End the active practice call first.');const revision=data.revision;data=D.demo(C);data.revision=revision;save('Practice workspace reset.');render();return;}
if(name==='practice-drill'){practiceDialog(button.dataset.category);return;}
if(name==='export-catalog'){download(JSON.stringify(catalog,null,2),'revenue-desk-catalog.json','application/json');return;}
if(name==='catalog'){openModal('Catalog reference sources','<p>These are reference records. Customer-level price and eligibility must still be verified.</p><div class="catalog-list">'+catalog.map(p=>'<div class="catalog-item"><b>'+h(p.name)+'</b><p style="margin-top:8px">'+h(p.scope)+'</p><small>'+h(p.source)+' · '+h(p.version)+'</small></div>').join('')+'</div>');return;}
if(name==='export-csv'){const rows=[['Customer','Business','Status','Source','Workflow','Need','Decision','Next step','Next step UTC','Customer agreed','Net collected USD'],...data.deals.map(d=>[d.name,d.business,C.status(data,d),d.source,d.cohort,d.facts.need,d.facts.decision,d.task?.purpose||'',d.task?.at||'',d.task?.confirmed?'yes':'no',(C.netPaid(data,d.id)/100).toFixed(2)])];const cell=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};download(rows.map(r=>r.map(cell).join(',')).join('\r\n'),'revenue-desk-deals-'+dateToday()+'.csv','text/csv');return;}
if(name==='restore-confirm'){if(!pendingImport)throw new Error('No validated backup is selected.');if(!dialog.querySelector('[name=replace-confirm]')?.checked)throw new Error('Confirm that you want to replace this workspace.');const revision=data.revision;data=pendingImport;data.revision=revision;pendingImport=null;conflict=false;storageWarning='';save('Backup restored.');closeModal();view='today';render();return;}
if(!d){dealDialog();return;}
if(name==='start-call'){C.startSession(data,d);save('Call started.');pane='flow';render();return;}
if(name==='end-call'){endDialog();return;}
if(name==='permission'){d.permission=true;d.rushed=button.dataset.value==='rushed';C.addHistory(d,d.rushed?'Customer agreed to a brief conversation':'Customer agreed to the conversation');refreshDeal(d,'Time and purpose agreed.');return;}
if(name==='coverage'){coverageDialog();return;}
if(name==='evidence'){evidenceDialog(button.dataset.key);return;}
if(name==='quote'){quoteDialog(button.dataset.product);return;}
if(name==='objection'){objectionDialog(button.dataset.category);return;}
if(name==='objection-chip'){dialog.querySelector('[name=clarification]').value=button.dataset.value;return;}
if(name==='task'){taskDialog();return;}
if(name==='accept'||name==='authorize'){agreementDialog(name);return;}
if(name==='payment'||name==='refund'){paymentDialog(name==='refund');return;}
if(name==='activate'){activationDialog();return;}
if(name==='decline'){declineDialog();return;}
if(name==='reopen'){reopenDialog();return;}
if(name==='complete-task'){if(d.task){d.task.done=true;C.addHistory(d,'Next step completed: '+d.task.purpose);refreshDeal(d,'Next step completed.');}return;}
if(name==='copy-recap'){await copy(C.recap(data,d));return;}
if(name==='copy-email'){if(d.doNotContact)throw new Error('This customer has asked not to be contacted.');await copy(C.email(data,d));return;}
if(name==='notes'){openModal('Working notes',form('notes',field('Notes for this customer','notes',d.notes,{textarea:true,rows:8}),'Save notes'));return;}
if(name==='silence'){silenceUntil=Date.now()+7000;updateTimers();return;}
if(name==='remove-quote'){if(d.acceptedAt)throw new Error('Reopen the accepted offer first.');d.quote=null;d.facts.fit='';d.facts.criterion='';C.addHistory(d,'Unaccepted recommendation removed');refreshDeal(d,'Recommendation removed. No revenue changed.');return;}
if(name==='unlock-offer'){if(C.grossPaid(data,d.id)>0)throw new Error('A paid offer is kept with its transaction history. Create a separate deal for a new purchase.');openModal('Reopen the offer',form('unlock',field('What changed?','reason','',{required:true,textarea:true,placeholder:'Record why the offer needs to change'})+'<p class="muted" style="font-size:12px">The prior agreement and authorization will be cleared. New terms require fresh customer agreement.</p>','Reopen offer'));return;}
}
async function submitForm(el){const f=Object.fromEntries(new FormData(el).entries()),kind=el.dataset.form,d=active(),now=new Date().toISOString();
if(kind==='deal'){
 const existing=data.deals.find(x=>x.id===el.dataset.id);const values={};for(const k of ['name','business','email','phone','industry','entity','source'])values[k]=String(f[k]||'').trim();if(!values.name)throw new Error('Enter the customer’s name.');
 if(existing){Object.assign(existing,values);if(!data.sessions.some(s=>s.dealId===existing.id))existing.cohort=f.cohort==='baseline'?'baseline':'adaptive';C.addHistory(existing,'Customer details updated');}
 else{const nd=C.deal({...values,cohort:f.cohort});data.deals.push(nd);data.activeId=nd.id;}
 save('Customer saved.');closeModal();view='desk';pane='flow';if(!existing)deskSection='overview';render();return;
}
if(kind==='settings'){
 new Intl.DateTimeFormat('en-US',{timeZone:f.timeZone});const target=Number(f.targetDeals);if(!Number.isInteger(target)||target<1||target>1000)throw new Error('Choose a daily goal between 1 and 1,000.');data.settings={...data.settings,repName:f.repName.trim(),targetDeals:target,timeZone:f.timeZone.trim()};document.documentElement.dataset.theme=f.theme;try{localStorage.setItem('rd_theme',f.theme);}catch(_){}save('Preferences saved.');closeModal();render();return;
}
if(kind==='drill'){const o=C.OBJECTIONS[f.category]||C.OBJECTIONS.thinking;openModal('Review your response','<div class="notice"><span class="eyebrow">YOUR RESPONSE</span><p style="margin-top:10px">'+h(f.response)+'</p></div><div style="margin-top:20px">'+check('acknowledge','I acknowledged the concern without arguing.')+check('clarify','I asked one clear question to understand the actual blocker.')+check('listen','I left room to listen instead of immediately pitching another option.')+'</div><div class="notice" style="margin-top:20px"><span class="eyebrow">A QUESTION TO TRY</span><p style="font-family:Georgia,serif;font-size:22px;margin-top:10px">'+h(o.question)+'</p></div><p class="explanation">Self-review only. No automated quality score is assigned.</p><div class="form-actions">'+btn('Try again','practice-drill','ghost','data-category="'+attr(f.category)+'"')+btn('Done','dismiss','primary')+'</div>');return;}
if(!d)throw new Error('Choose a customer first.');
if(kind==='answer'){const key=el.dataset.key;if(!C.FACTS[key])throw new Error('Unknown evidence field.');d.facts[key]=f.answer.trim();if(!d.facts[key])throw new Error('Record what the customer actually said.');if(key==='decision'){d.decisionType=f.decisionType;d.decisionReady=!!f.decisionReady;}C.addHistory(d,C.FACTS[key]+' captured: '+d.facts[key]);answerDraft='';if(dialog.open)closeModal();refreshDeal(d,'Buyer evidence saved.');return;}
if(kind==='evidence'){for(const k of Object.keys(C.FACTS))d.facts[k]=String(f[k]||'').trim();d.decisionType=f.decisionType;d.decisionReady=!!f.decisionReady;C.addHistory(d,'Buyer evidence updated');}
else if(kind==='coverage'){for(const k of Object.keys(C.SERVICES)){if(!['unknown','covered','gap','na'].includes(f[k]))throw new Error('Choose a valid coverage state.');d.coverage[k]=f[k];d.coverageNotes[k]=String(f['note-'+k]||'').trim();}C.addHistory(d,'Coverage confirmed from account and customer');}
else if(kind==='quote'){
 const p=catalog.find(p=>p.id===f.productId);if(!p)throw new Error('Product not found.');const months=Number(f.months);const expires=new Date(f.expires+'T23:59:59').toISOString();
 const q={id:C.uid(),lines:[{productId:p.id,name:p.name,amount:C.cents(f.amount),services:[...p.services],billing:f.billing,months}],scope:f.scope.trim(),terms:f.terms.trim(),source:f.source.trim(),verified:!!f.verified,verifiedAt:now,expiresAt:expires,catalogVersion:p.version};C.saveQuote(d,q);pane='offer';
}
else if(kind==='objection'){if(!C.OBJECTIONS[f.category])throw new Error('Choose a concern category.');if(f.resolved&&(!f.clarification.trim()||!f.resolution.trim()))throw new Error('Record the clarified concern, the answer, and the customer’s confirmation before marking it resolved.');d.objection={category:f.category,quote:f.quote.trim(),clarification:f.clarification.trim(),resolution:f.resolution.trim(),resolved:!!f.resolved};C.addHistory(d,(d.objection.resolved?'Concern resolved: ':'Concern captured: ')+d.objection.quote);}
else if(kind==='task'){const at=new Date(f.at).toISOString();if(d.doNotContact&&f.confirmed)throw new Error('This customer asked not to be contacted. Reopen only at their request.');d.task={id:C.uid(),kind:f.kind,purpose:f.purpose.trim(),at,owner:f.owner.trim(),confirmed:!!f.confirmed,done:false};if(!d.task.purpose||!d.task.owner)throw new Error('Record a purpose and owner.');C.addHistory(d,d.task.confirmed?'Customer agreed to follow-up':'Internal next step created');C.addHistory(d,'Next step: '+d.task.purpose+' · '+at);}
else if(kind==='accept'||kind==='authorize'){if(!f.confirmed)throw new Error('Confirm the customer’s explicit '+(kind==='accept'?'agreement':'authorization')+'.');if(kind==='accept')C.accept(d);else C.authorize(d);pane='offer';}
else if(kind==='payment'){C.recordPayment(data,d,{amount:C.cents(f.amount),reference:f.reference,confirmed:!!f.confirmed});pane='offer';}
else if(kind==='refund'){C.recordRefund(data,d,{paymentId:f.paymentId,amount:C.cents(f.amount),reference:f.reference,confirmed:!!f.confirmed});pane='offer';}
else if(kind==='activation'){if(!f.confirmed||!f.detail.trim())throw new Error('Record and confirm the completed activation step.');C.activate(data,d);C.addHistory(d,'Activation detail: '+f.detail.trim());}
else if(kind==='end-call'){C.endSession(data,d,f.outcome);pane='follow';}
else if(kind==='decline'){d.disposition='declined';d.lossReason=f.reason;d.doNotContact=!!f.doNotContact;if(d.task)d.task.done=true;C.addHistory(d,'Customer declined: '+f.reason+' · '+f.detail.trim());if(d.doNotContact)C.addHistory(d,'Customer requested no further contact');}
else if(kind==='reopen'){if(!f.confirmed)throw new Error('Confirm the customer requested to reopen.');d.disposition='open';d.doNotContact=false;d.lossReason='';d.acceptedAt=null;d.authorizedAt=null;d.permission=false;C.addHistory(d,'Customer requested to reopen: '+f.detail.trim());}
else if(kind==='unlock'){d.acceptedAt=null;d.authorizedAt=null;d.facts.fit='';d.facts.criterion='';C.addHistory(d,'Offer reopened; fresh agreement required: '+f.reason.trim());}
else if(kind==='notes'){d.notes=f.notes;}
else return;
save('Saved to this customer.');closeModal();render();if(kind==='end-call')jumpToSection('recap');
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();Promise.resolve(handleAction(b)).catch(err=>{if(dialog.open){const box=dialog.querySelector('.form-error');if(box){box.textContent=err.message;return;}}toast(err.message||'That action could not be completed.');});});
document.addEventListener('submit',e=>{const el=e.target.closest('[data-form]');if(!el)return;e.preventDefault();const box=el.querySelector('.form-error');if(box)box.textContent='';Promise.resolve(submitForm(el)).catch(err=>{if(box)box.textContent=err.message||'Check the fields and try again.';else toast(err.message);});});
let searchTimer;
document.addEventListener('input',e=>{
if(e.target.id==='jump-query'){document.getElementById('jump-results').innerHTML=Desk.searchResults(e.target.value);return;}
if(e.target.id==='buyer-answer'){answerDraft=e.target.value;return;}
if(e.target.id==='deal-search'){query=e.target.value;clearTimeout(searchTimer);const start=e.target.selectionStart;searchTimer=setTimeout(()=>{render();const input=document.getElementById('deal-search');input?.focus();try{input?.setSelectionRange(start,start);}catch(_){}},180);return;}
if(['call-notes','modal-call-notes'].includes(e.target.id)){const d=active();if(d){d.notes=e.target.value;d.updatedAt=new Date().toISOString();clearTimeout(noteTimer);noteTimer=setTimeout(()=>save(),350);}return;}
});
document.addEventListener('change',async e=>{try{
if(e.target.id==='lane'){const d=active();d.lane=e.target.value;refreshDeal(d,'Conversation focus updated.');return;}
if(e.target.name==='category'&&e.target.closest('[data-form=objection]')){const o=C.OBJECTIONS[e.target.value];document.getElementById('objection-question').innerHTML='<span class="eyebrow">ASK TO CLARIFY</span><p style="margin-top:9px">'+h(o.question)+'</p>';document.getElementById('objection-options').innerHTML=o.options.map(t=>'<button type="button" data-action="objection-chip" data-value="'+attr(t)+'">'+h(t)+'</button>').join('');return;}
if(['restore-file','catalog-file'].includes(e.target.id)){
const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('Choose a JSON file smaller than 10 MB.');const value=JSON.parse(await file.text());
if(e.target.id==='catalog-file'){data.catalog=D.validateCatalog(value);save('Catalog imported. Customer quotes still need verification.');catalogNow();settingsDialog();return;}
if(live())throw new Error('End the active call before restoring a backup.');pendingImport=C.validateWorkspace(value);if(pendingImport.catalog)pendingImport.catalog=D.validateCatalog(pendingImport.catalog);
openModal('Review the backup before restoring','<p>This will replace the '+(practice?'practice':'real')+' workspace in this browser.</p><div class="notice"><b>Current workspace:</b> '+data.deals.length+' deals, '+data.events.length+' transaction records.<br><b>Selected backup:</b> '+pendingImport.deals.length+' deals, '+pendingImport.events.length+' transaction records.</div><div style="margin-top:18px">'+btn('Export current workspace first','backup','ghost')+'</div>'+check('replace-confirm','Replace this workspace with the selected backup.')+'<div class="form-error" role="alert"></div><div class="form-actions">'+btn('Cancel','dismiss','ghost')+btn('Restore backup','restore-confirm','primary')+'</div>');}
}catch(err){toast(err.message||'This file could not be read.');}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
window.addEventListener('storage',e=>{if(e.key!==(practice?DEMO_KEY:KEY))return;conflict=true;storageWarning='Another tab updated this workspace. Export any unsaved work and reload before continuing.';renderWarning();});
window.addEventListener('beforeunload',e=>{if(storageWarning||conflict){e.preventDefault();e.returnValue='';}else if(noteTimer){clearTimeout(noteTimer);persist();}});
document.addEventListener('keydown',e=>{
 const key=e.key.toLowerCase(),typing=e.target.closest('input,textarea,select,[contenteditable]');
 if((e.metaKey||e.ctrlKey)&&key==='k'){e.preventDefault();jumpDialog();return;}
 if(e.target.id==='jump-query'&&e.key==='Enter'){e.preventDefault();document.getElementById('jump-results')?.querySelector('.jump-result')?.click();return;}
 if(dialog.open||typing)return;
 if(e.altKey&&view==='desk'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const i=Desk.sections.findIndex(s=>s.id===deskSection),next=Math.max(0,Math.min(Desk.sections.length-1,i+(e.key==='ArrowRight'?1:-1)));jumpToSection(Desk.sections[next].id);return;}
 if(e.metaKey||e.ctrlKey||e.altKey)return;
 if(key==='n'){e.preventDefault();dealDialog();}
 else if(key==='d'){e.preventDefault();setView('desk');}
 else if(key==='h'){e.preventDefault();setView('today');}
 else if(key==='o'){e.preventDefault();jumpToSection('objections');}
 else if(key==='p'){e.preventDefault();jumpToSection('offers');}
 else if(key==='f'&&view==='desk'){e.preventDefault();deskFocus=!deskFocus;jumpToSection(deskSection);}
 else if(key==='m'){e.preventDefault();if(active())handleAction({dataset:{action:'notes'}});else dealDialog();}
 else if(e.key==='/'){e.preventDefault();jumpDialog();}
});
try{const theme=localStorage.getItem('rd_theme');if(theme==='light'||theme==='dark')document.documentElement.dataset.theme=theme;}catch(_){}
if(!conflict)persist();render();setInterval(updateTimers,1000);
})();
